/* ------------------------------ Desglose por categoría ------------------------------ */

function DesgloseCategorias({ titulo, datos, color, icon: Icon }) {
  const max = Math.max(1, ...datos.map((d) => d.total));
  const total = datos.reduce((s, d) => s + d.total, 0);
  return (
    <Card>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, fontWeight: 700, color: theme.ink }}>
          <Icon size={17} color={color} />
          {titulo}
        </div>
        <div style={{ fontFamily: "Playfair Display, serif", fontWeight: 700, fontSize: 18, color }}>
          {fmtEUR(total)}
        </div>
      </div>
      {datos.length === 0 && (
        <div style={{ fontSize: 13, color: theme.inkSoft, padding: "8px 0" }}>Sin movimientos en este periodo.</div>
      )}
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {datos.map((d) => (
          <div key={d.category}>
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, marginBottom: 4 }}>
              <span style={{ fontWeight: 600, color: theme.ink, display: "flex", alignItems: "center", gap: 6 }}>
                {d.category}
                {d.automatico && (
                  <span style={{ fontSize: 10, fontWeight: 700, color, background: color + "22", borderRadius: 999, padding: "1px 7px" }}>
                    ● en vivo
                  </span>
                )}
              </span>
              <span style={{ color: theme.inkSoft, fontWeight: 600 }}>{fmtEUR(d.total)}</span>
            </div>
            <div style={{ height: 7, borderRadius: 999, background: theme.border, overflow: "hidden" }}>
              <div style={{ height: "100%", width: `${(d.total / max) * 100}%`, background: color, borderRadius: 999, transition: "width .3s" }} />
            </div>
          </div>
        ))}
      </div>
    </Card>
  );
}

/* ------------------------------ Configurar categorías ------------------------------ */

function ModalCategorias({ categorias, onClose, onGuardar }) {
  const [ingresos, setIngresos] = useState(categorias.ingresos);
  const [gastos, setGastos] = useState(categorias.gastos);
  const [subcategorias, setSubcategorias] = useState(categorias.subcategorias || {});
  const [nuevoIngreso, setNuevoIngreso] = useState("");
  const [nuevoGasto, setNuevoGasto] = useState("");
  const [catExpandida, setCatExpandida] = useState(null);
  const [nuevaSub, setNuevaSub] = useState("");

  const Chip = ({ label, onQuitar }) => (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 6, background: theme.bg,
      border: `1px solid ${theme.border}`, borderRadius: 999, padding: "5px 6px 5px 12px", fontSize: 13,
    }}>
      {label}
      <button onClick={onQuitar} style={{ border: "none", background: "none", cursor: "pointer", color: theme.inkSoft, display: "flex" }}>
        <X size={13} />
      </button>
    </span>
  );

  function agregarSub(cat) {
    if (!nuevaSub.trim()) return;
    const actuales = subcategorias[cat] || [];
    if (actuales.includes(nuevaSub.trim())) { setNuevaSub(""); return; }
    setSubcategorias({ ...subcategorias, [cat]: [...actuales, nuevaSub.trim()] });
    setNuevaSub("");
  }
  function quitarSub(cat, sub) {
    setSubcategorias({ ...subcategorias, [cat]: (subcategorias[cat] || []).filter((s) => s !== sub) });
  }
  function quitarCategoria(cat, lista, setLista) {
    setLista(lista.filter((x) => x !== cat));
    const { [cat]: _omit, ...resto } = subcategorias;
    setSubcategorias(resto);
    if (catExpandida === cat) setCatExpandida(null);
  }

  const BloqueCategorias = ({ titulo, color, lista, setLista, nuevo, setNuevo, placeholder }) => (
    <div style={{ marginBottom: 22 }}>
      <div style={{ fontSize: 13, fontWeight: 700, color, marginBottom: 8 }}>{titulo}</div>
      <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: 10 }}>
        {lista.map((c) => (
          <div key={c} style={{ border: `1px solid ${theme.border}`, borderRadius: 10, padding: "8px 10px" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <button
                onClick={() => setCatExpandida(catExpandida === c ? null : c)}
                style={{ border: "none", background: "none", cursor: "pointer", display: "flex", alignItems: "center", gap: 6, fontSize: 13, fontWeight: 600, color: theme.ink, padding: 0 }}
              >
                {catExpandida === c ? "▾" : "▸"} {c}
                {(subcategorias[c] || []).length > 0 && (
                  <span style={{ fontSize: 11, color: theme.inkSoft, fontWeight: 400 }}>({subcategorias[c].length} subcat.)</span>
                )}
              </button>
              <button onClick={() => quitarCategoria(c, lista, setLista)} style={{ border: "none", background: "none", cursor: "pointer", color: theme.inkSoft, display: "flex" }}>
                <X size={13} />
              </button>
            </div>
            {catExpandida === c && (
              <div style={{ marginTop: 10, paddingTop: 10, borderTop: `1px solid ${theme.border}` }}>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 8 }}>
                  {(subcategorias[c] || []).map((s) => <Chip key={s} label={s} onQuitar={() => quitarSub(c, s)} />)}
                  {(subcategorias[c] || []).length === 0 && (
                    <span style={{ fontSize: 12, color: theme.inkSoft }}>Sin subcategorías todavía.</span>
                  )}
                </div>
                <div style={{ display: "flex", gap: 6 }}>
                  <input value={nuevaSub} onChange={(e) => setNuevaSub(e.target.value)}
                    onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); agregarSub(c); } }}
                    placeholder="Nueva subcategoría…"
                    style={{ flex: 1, padding: "6px 8px", borderRadius: 6, border: `1px solid ${theme.border}`, fontSize: 12.5 }} />
                  <button onClick={() => agregarSub(c)}
                    style={{ padding: "6px 10px", borderRadius: 6, border: "none", background: color, color: "#fff", fontWeight: 700, cursor: "pointer" }}>
                    <Plus size={12} />
                  </button>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        <input value={nuevo} onChange={(e) => setNuevo(e.target.value)} placeholder={placeholder}
          style={{ flex: 1, padding: "8px 10px", borderRadius: 8, border: `1px solid ${theme.border}`, fontSize: 13 }} />
        <button onClick={() => { if (nuevo.trim()) { setLista([...lista, nuevo.trim()]); setNuevo(""); } }}
          style={{ padding: "8px 14px", borderRadius: 8, border: "none", background: color, color: "#fff", fontWeight: 700, cursor: "pointer" }}>
          <Plus size={14} />
        </button>
      </div>
    </div>
  );

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(28,43,34,0.35)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 60 }}>
      <div style={{ background: theme.surface, borderRadius: 16, padding: 26, width: 520, maxHeight: "85vh", overflowY: "auto" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
          <div style={{ fontWeight: 700, fontSize: 17, color: theme.ink }}>Configurar categorías</div>
          <button onClick={onClose} style={{ border: "none", background: "none", cursor: "pointer" }}><X size={18} /></button>
        </div>
        <div style={{ fontSize: 12.5, color: theme.inkSoft, marginBottom: 18 }}>
          Toca una categoría para desplegarla y añadirle subcategorías.
        </div>

        <BloqueCategorias titulo="Categorías de ingreso" color={theme.success} lista={ingresos} setLista={setIngresos}
          nuevo={nuevoIngreso} setNuevo={setNuevoIngreso} placeholder="Nueva categoría de ingreso…" />

        <BloqueCategorias titulo="Partidas de gasto" color={theme.danger} lista={gastos} setLista={setGastos}
          nuevo={nuevoGasto} setNuevo={setNuevoGasto} placeholder="Nueva partida de gasto…" />

        <button
          onClick={() => { onGuardar({ ingresos, gastos, subcategorias }); onClose(); }}
          style={{ width: "100%", padding: "11px 0", borderRadius: 10, border: "none", background: theme.accent, color: "#fff", fontWeight: 700, cursor: "pointer" }}
        >
          Guardar categorías
        </button>
      </div>
    </div>
  );
}

/* ------------------------------------- Resumen (dashboard) ------------------------------------- */

// Ventas del Excel (colección ventas_gcr / ventas_jmcf) para el Resumen: se leen solo los meses que hacen falta.
const xlTitulo = (s) => String(s || "Sin familia").toLowerCase().replace(/(^|\s)\S/g, (c) => c.toUpperCase());

function ResumenView({ transacciones: transaccionesProp, presupuestos, metas, ventasProshop: ventasProshopProp, categorias, onGuardarCategorias, tenantId, ventasEnt, negocio }) {
  const now = new Date();
  const [preset, setPreset] = useState("mes");
  const [desdeManual, setDesdeManual] = useState(new Date(now.getFullYear(), now.getMonth(), 1).toISOString().slice(0, 10));
  const [hastaManual, setHastaManual] = useState(now.toISOString().slice(0, 10));
  const [modalCategorias, setModalCategorias] = useState(false);
  const [compararAnio, setCompararAnio] = useState(false);
  const [compararPresupuesto, setCompararPresupuesto] = useState(false);

  const { desde, hasta } = useMemo(() => calcularRango(preset, desdeManual, hastaManual), [preset, desdeManual, hastaManual]);

  // --- Ventas del Excel: se cargan los meses del periodo (y los 12 anteriores, para "vs. año anterior") ---
  const xlCache = useRef({});
  const [xl, setXl] = useState({ lineas: [], maxPorMes: {}, maxNeg: {} });
  const [xlCargando, setXlCargando] = useState(false);
  useEffect(() => {
    let vivo = true;
    (async () => {
      if (!tenantId || !ventasEnt) return;
      const col = VG_ENTS[ventasEnt]?.col;
      if (!col) return;
      setXlCargando(true);
      const ini = new Date(desde); ini.setFullYear(ini.getFullYear() - 1);
      const ids = [];
      for (let y = ini.getFullYear(), m = ini.getMonth(); y < hasta.getFullYear() || (y === hasta.getFullYear() && m <= hasta.getMonth()); ) {
        ids.push(`${y}-${String(m + 1).padStart(2, "0")}`);
        m += 1; if (m > 11) { m = 0; y += 1; }
        if (ids.length > 72) break;
      }
      const lineas = [];
      const maxPorMes = {};
      const maxNeg = { proshop: {}, academia: {} }; // última fecha cubierta por el Excel de cada negocio (Pro Shop y Academia van por separado)
      for (const id of ids) {
        const clave = `${col}/${id}`;
        if (!(clave in xlCache.current)) {
          try {
            const snap = await getDoc(doc(db, `clubes/${tenantId}/${col}`, id));
            xlCache.current[clave] = snap.exists() ? snap.data().lineas || [] : null;
          } catch (e) {
            xlCache.current[clave] = null; // sin permiso o sin datos: el resumen sigue con lo que hay
          }
        }
        const ls = xlCache.current[clave];
        if (ls && ls.length) {
          ls.forEach((l) => lineas.push({ date: `${l.d}T12:00:00`, d: l.d, total: Number(l.t || 0), category: xlTitulo(l.f), negocio: /academia/i.test(String(l.f || "")) ? "academia" : "proshop" }));
          // Una línea mensual (m:1) cubre el mes entero; una diaria, hasta su día.
          const cubre = (l) => (l.m ? vgFinMes(Number(id.slice(0, 4)), Number(id.slice(5, 7))) : l.d);
          maxPorMes[id] = ls.reduce((mx, l) => (cubre(l) > mx ? cubre(l) : mx), "");
          ls.forEach((l) => {
            const n = /academia/i.test(String(l.f || "")) ? "academia" : "proshop";
            if (!maxNeg[n][id] || cubre(l) > maxNeg[n][id]) maxNeg[n][id] = cubre(l);
          });
        }
      }
      if (vivo) { setXl({ lineas, maxPorMes, maxNeg }); setXlCargando(false); }
    })();
    return () => { vivo = false; };
  }, [tenantId, ventasEnt, desde, hasta]);

  // Para no contar dos veces: donde el Excel tiene ventas (hasta su última fecha de ese mes),
  // no se cuentan las ventas "Ventas Campo" de Transacciones (club) ni Academia/Proshop automáticos (JMCF).
  const cubiertoPorExcel = (fecha, neg) => {
    const f = aFecha(fecha);
    if (!f || isNaN(f)) return false;
    const d = `${f.getFullYear()}-${String(f.getMonth() + 1).padStart(2, "0")}-${String(f.getDate()).padStart(2, "0")}`;
    // En JMCF cada negocio se compara con las ventas de SU familia; si el Excel no trae Academia ese mes, los cobros de Academia no se descartan.
    const mx = ventasEnt === "jmcf" && neg ? xl.maxNeg?.[neg]?.[d.slice(0, 7)] : xl.maxPorMes[d.slice(0, 7)];
    return !!mx && d <= mx;
  };
  const transacciones = useMemo(
    () => transaccionesProp.filter((t) => {
      const esVentaDuplicable = ventasEnt === "jmcf"
        ? (t.type === "income" && (String(t.id).startsWith("academia-") || t.origen === "academia"))
        : (t.type === "income" && normTx(t.category) === "ventas campo");
      return !(esVentaDuplicable && cubiertoPorExcel(t.date, "academia"));
    }),
    [transaccionesProp, xl, ventasEnt]
  );
  const ventasProshop = useMemo(() => ventasProshopProp.filter((v) => !cubiertoPorExcel(v.creadoEn, "proshop")), [ventasProshopProp, xl]);

  const enRango = (t) => { const f = aFecha(t.date); return f >= desde && f <= hasta; };
  const delRango = transacciones.filter(enRango);

  const ingresosManual = delRango.filter((t) => t.type === "income");
  const gastosManual = delRango.filter((t) => t.type === "expense");

  const ventasProshopRango = ventasProshop.filter((v) => { const f = aFecha(v.creadoEn); return f >= desde && f <= hasta; });
  const totalProshopAuto = ventasProshopRango.reduce((s, v) => s + Number(v.total || 0), 0);

  const xlLineas = useMemo(
    () => (ventasEnt === "jmcf" && negocio && negocio !== "todo" ? xl.lineas.filter((l) => l.negocio === negocio) : xl.lineas),
    [xl, negocio, ventasEnt]
  );
  const ventasXlRango = xlLineas.filter((l) => { const f = aFecha(l.date); return f >= desde && f <= hasta; });
  const totalXl = ventasXlRango.reduce((s, l) => s + l.total, 0);

  const totalIngresos = ingresosManual.reduce((s, t) => s + Number(t.amount), 0) + totalProshopAuto + totalXl;
  const totalGastos = gastosManual.reduce((s, t) => s + Number(t.amount), 0);
  const balance = totalIngresos - totalGastos;

  const agruparPorCategoria = (items) => {
    const mapa = {};
    items.forEach((t) => { const c = t.category || "Sin categoría"; mapa[c] = (mapa[c] || 0) + Number(t.amount || 0); });
    return Object.entries(mapa).map(([category, total]) => ({ category, total }));
  };

  const desgloseIngresos = useMemo(() => {
    const base = agruparPorCategoria(ingresosManual).filter((d) => d.category !== "Proshop");
    if (totalProshopAuto > 0 || ventasProshopRango.length > 0) {
      base.push({ category: "Proshop", total: totalProshopAuto, automatico: true });
    }
    const porFamilia = {};
    ventasXlRango.forEach((l) => { porFamilia[l.category] = (porFamilia[l.category] || 0) + l.total; });
    Object.entries(porFamilia).forEach(([category, total]) => base.push({ category: `Ventas · ${category}`, total: Math.round(total * 100) / 100, automatico: true }));
    return base.sort((a, b) => b.total - a.total);
  }, [ingresosManual, totalProshopAuto, ventasXlRango]);

  const desgloseGastos = useMemo(() => agruparPorCategoria(gastosManual).sort((a, b) => b.total - a.total), [gastosManual]);

  const totalPresupuestoMensual = useMemo(
    () => presupuestos.reduce((s, p) => s + Number(p.monthly_limit || 0), 0),
    [presupuestos]
  );

  const comparativo = useMemo(() => {
    const buckets = generarBuckets(desde, hasta);
    return buckets.map((b) => {
      const diasBucket = Math.max(1, Math.round((b.fin - b.inicio) / 86400000) + 1);

      const ingB = sumaEnRango(transacciones, b.inicio, b.fin, "date", "amount", (t) => t.type === "income")
        + sumaEnRango(ventasProshop, b.inicio, b.fin, "creadoEn", "total")
        + sumaEnRango(xlLineas, b.inicio, b.fin, "date", "total");
      const gasB = sumaEnRango(transacciones, b.inicio, b.fin, "date", "amount", (t) => t.type === "expense");

      const inicioAnt = new Date(b.inicio); inicioAnt.setFullYear(inicioAnt.getFullYear() - 1);
      const finAnt = new Date(b.fin); finAnt.setFullYear(finAnt.getFullYear() - 1);
      const ingAnt = sumaEnRango(transacciones, inicioAnt, finAnt, "date", "amount", (t) => t.type === "income")
        + sumaEnRango(ventasProshop, inicioAnt, finAnt, "creadoEn", "total")
        + sumaEnRango(xlLineas, inicioAnt, finAnt, "date", "total");
      const gasAnt = sumaEnRango(transacciones, inicioAnt, finAnt, "date", "amount", (t) => t.type === "expense");

      const presupuestoB = totalPresupuestoMensual * (diasBucket / 30.44);

      return {
        periodo: b.label,
        Ingresos: ingB,
        Gastos: gasB,
        "Ingresos (año ant.)": ingAnt,
        "Gastos (año ant.)": gasAnt,
        "Presupuesto gastos": presupuestoB,
      };
    });
  }, [desde, hasta, transacciones, ventasProshop, xlLineas, totalPresupuestoMensual]);

  const currentMonth = monthKey(now.toISOString());
  const delMes = transacciones.filter((t) => monthKey(t.date) === currentMonth);
  const presupuestosAlerta = presupuestos
    .map((p) => {
      const gastado = gastoDePresupuesto(p, delMes) + nominasDePresupuesto(p, now.getMonth() + 1, delMes);
      return { ...p, gastado, pct: (gastado / Number(p.monthly_limit)) * 100 };
    })
    .filter((p) => p.pct >= 80)
    .sort((a, b) => b.pct - a.pct);

  const metasProximas = [...metas]
    .filter((m) => m.deadline)
    .sort((a, b) => new Date(a.deadline?.toDate?.() || a.deadline) - new Date(b.deadline?.toDate?.() || b.deadline))
    .slice(0, 3);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 12 }}>
        <SelectorRango preset={preset} setPreset={setPreset} desdeManual={desdeManual} setDesdeManual={setDesdeManual} hastaManual={hastaManual} setHastaManual={setHastaManual} />
        <button
          onClick={() => setModalCategorias(true)}
          style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 14px", borderRadius: 10, border: `1px solid ${theme.border}`, background: theme.surface, color: theme.inkSoft, fontWeight: 600, fontSize: 13, cursor: "pointer" }}
        >
          <Settings size={15} /> Configurar categorías
        </button>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 16 }}>
        <Card style={{ padding: 0, overflow: "hidden" }}>
          <div style={{ height: 3, background: theme.success }} />
          <div style={{ padding: 20 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, color: theme.success }}>
              <TrendingUp size={18} />
              <span style={{ fontSize: 13, fontWeight: 600 }}>Ingresos</span>
            </div>
            <div style={{ fontSize: 28, fontWeight: 700, marginTop: 10, color: theme.ink, fontFamily: "Playfair Display, serif" }}>
              {fmtEUR(totalIngresos)}
            </div>
            {xlCargando && <div style={{ fontSize: 11.5, color: theme.inkSoft, marginTop: 4 }}>Cargando ventas…</div>}
          </div>
        </Card>
        <Card style={{ padding: 0, overflow: "hidden" }}>
          <div style={{ height: 3, background: theme.danger }} />
          <div style={{ padding: 20 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, color: theme.danger }}>
              <TrendingDown size={18} />
              <span style={{ fontSize: 13, fontWeight: 600 }}>Gastos</span>
            </div>
            <div style={{ fontSize: 28, fontWeight: 700, marginTop: 10, color: theme.ink, fontFamily: "Playfair Display, serif" }}>
              {fmtEUR(totalGastos)}
            </div>
          </div>
        </Card>
        <Card style={{ padding: 0, overflow: "hidden" }}>
          <div style={{ height: 3, background: theme.accent }} />
          <div style={{ padding: 20 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, color: theme.accent }}>
              <Wallet size={18} />
              <span style={{ fontSize: 13, fontWeight: 600 }}>Balance</span>
            </div>
            <div style={{ fontSize: 28, fontWeight: 700, marginTop: 10, color: balance >= 0 ? theme.ink : theme.danger, fontFamily: "Playfair Display, serif" }}>
              {fmtEUR(balance)}
            </div>
          </div>
        </Card>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
        <DesgloseCategorias titulo="Ingresos por categoría" datos={desgloseIngresos} color={theme.success} icon={TrendingUp} />
        <DesgloseCategorias titulo="Gastos por partida" datos={desgloseGastos} color={theme.danger} icon={TrendingDown} />
      </div>

      <Card>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 10, marginBottom: 14 }}>
          <div style={{ fontWeight: 700, color: theme.ink }}>
            Ingresos vs. Gastos <span style={{ fontWeight: 400, color: theme.inkSoft, fontSize: 12.5 }}>· periodo seleccionado</span>
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            <button
              onClick={() => setCompararAnio(!compararAnio)}
              style={{
                padding: "6px 12px", borderRadius: 999, fontSize: 12.5, fontWeight: 600, cursor: "pointer",
                border: `1px solid ${compararAnio ? theme.accent : theme.border}`,
                background: compararAnio ? theme.accentSoft : "transparent",
                color: compararAnio ? "#8A6A2E" : theme.inkSoft,
              }}
            >
              vs. año anterior
            </button>
            <button
              onClick={() => setCompararPresupuesto(!compararPresupuesto)}
              style={{
                padding: "6px 12px", borderRadius: 999, fontSize: 12.5, fontWeight: 600, cursor: "pointer",
                border: `1px solid ${compararPresupuesto ? theme.accent : theme.border}`,
                background: compararPresupuesto ? theme.accentSoft : "transparent",
                color: compararPresupuesto ? "#8A6A2E" : theme.inkSoft,
              }}
            >
              vs. presupuesto
            </button>
          </div>
        </div>
        <div style={{ width: "100%", height: 280 }}>
          <ResponsiveContainer>
            <LineChart data={comparativo}>
              <CartesianGrid stroke={theme.border} vertical={false} />
              <XAxis dataKey="periodo" stroke={theme.inkSoft} fontSize={11} />
              <YAxis stroke={theme.inkSoft} fontSize={12} />
              <Tooltip formatter={(v) => fmtEUR(v)} />
              <Line type="monotone" dataKey="Ingresos" stroke={theme.success} strokeWidth={2.5} dot={false} />
              <Line type="monotone" dataKey="Gastos" stroke={theme.danger} strokeWidth={2.5} dot={false} />
              {compararAnio && (
                <>
                  <Line type="monotone" dataKey="Ingresos (año ant.)" stroke={theme.success} strokeWidth={1.5} strokeDasharray="5 4" dot={false} opacity={0.55} />
                  <Line type="monotone" dataKey="Gastos (año ant.)" stroke={theme.danger} strokeWidth={1.5} strokeDasharray="5 4" dot={false} opacity={0.55} />
                </>
              )}
              {compararPresupuesto && (
                <Line type="monotone" dataKey="Presupuesto gastos" stroke={theme.accent} strokeWidth={1.5} strokeDasharray="2 3" dot={false} />
              )}
            </LineChart>
          </ResponsiveContainer>
        </div>
        {totalPresupuestoMensual === 0 && compararPresupuesto && (
          <div style={{ fontSize: 12, color: theme.inkSoft, marginTop: 8 }}>
            Aún no tienes presupuestos configurados en "Presupuestos" — la línea de presupuesto estará en 0€ hasta que crees alguno.
          </div>
        )}
      </Card>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
        <Card>
          <div style={{ fontWeight: 700, marginBottom: 12, color: theme.ink }}>
            Presupuestos a vigilar <span style={{ fontWeight: 400, color: theme.inkSoft, fontSize: 12 }}>(mes en curso)</span>
          </div>
          {presupuestosAlerta.length === 0 && (
            <div style={{ fontSize: 13, color: theme.inkSoft }}>
              Ninguna categoría por encima del 80% este mes.
            </div>
          )}
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {presupuestosAlerta.map((p) => (
              <div key={p.id}>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, marginBottom: 4 }}>
                  <span style={{ fontWeight: 600 }}>{p.category}</span>
                  <span style={{ color: theme.inkSoft }}>
                    {fmtEUR(p.gastado)} / {fmtEUR(p.monthly_limit)}
                  </span>
                </div>
                <ProgressBar value={p.gastado} max={Number(p.monthly_limit)} />
              </div>
            ))}
          </div>
        </Card>

        <Card>
          <div style={{ fontWeight: 700, marginBottom: 12, color: theme.ink }}>
            Metas más próximas
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {metasProximas.map((m) => (
              <div key={m.id}>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, marginBottom: 4 }}>
                  <span style={{ fontWeight: 600 }}>{m.title}</span>
                  <span style={{ color: theme.inkSoft }}>{fmtDate(m.deadline)}</span>
                </div>
                <ProgressBar value={Number(m.current_amount)} max={Number(m.target_amount)} color={theme.accent} />
              </div>
            ))}
          </div>
        </Card>
      </div>

      {modalCategorias && (
        <ModalCategorias categorias={categorias} onClose={() => setModalCategorias(false)} onGuardar={onGuardarCategorias} />
      )}
    </div>
  );
}

/* ---------------------------- Transacciones ------------------------------ */

/* ------------------------- Escanear ticket (OCR) -------------------------- */

// Interpreta el texto bruto reconocido en la foto del ticket y saca
// un importe, una fecha y una descripción razonables. No es perfecto:
// el usuario siempre revisa y corrige antes de guardar.
function extraerDatosTicket(texto) {
  const lineas = texto.split("\n").map((l) => l.trim()).filter(Boolean);
  const regexImporte = /(\d{1,4}[.,]\d{2})/g;

  // Importe: prioriza la línea que contiene "total"; si no, coge el
  // número más alto de todo el ticket (suele ser el total, no una unidad)
  let importe = null;
  const lineaTotal = lineas.find((l) => /total/i.test(l));
  if (lineaTotal) {
    const m = [...lineaTotal.matchAll(regexImporte)];
    if (m.length) importe = m[m.length - 1][1].replace(",", ".");
  }
  if (!importe) {
    const todos = [...texto.matchAll(regexImporte)].map((m) => parseFloat(m[1].replace(",", ".")));
    if (todos.length) importe = Math.max(...todos).toFixed(2);
  }

  // Fecha: formatos dd/mm/yyyy, dd-mm-yyyy, dd.mm.yy...
  let fecha = null;
  const mFecha = texto.match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
  if (mFecha) {
    let [, d, m, y] = mFecha;
    if (y.length === 2) y = "20" + y;
    const fechaProbable = new Date(`${y}-${m.padStart(2, "0")}-${d.padStart(2, "0")}`);
    if (!isNaN(fechaProbable) && fechaProbable <= new Date()) {
      fecha = `${y}-${m.padStart(2, "0")}-${d.padStart(2, "0")}`;
    }
  }

  // Descripción: primera línea con contenido real (evita líneas de solo números/símbolos)
  const descripcion = lineas.find((l) => l.length > 3 && /[a-zA-ZÀ-ÿ]{3,}/.test(l)) || "";

  return {
    amount: importe || "",
    date: fecha || new Date().toISOString().slice(0, 10),
    description: descripcion.slice(0, 60),
  };
}

function EscanearTicketModal({ onClose, onDetectado, tenantId }) {
  const [imagen, setImagen] = useState(null);
  const [nombrePdf, setNombrePdf] = useState(null);
  const [procesando, setProcesando] = useState(false);
  const [error, setError] = useState("");

  // Guarda el archivo original en Storage y devuelve su ruta para enlazarlo a la transacción.
  // Si falla, devuelve el motivo (se enseña en el formulario) en vez de callarlo.
  const guardarArchivo = async (file, porDefecto) => {
    try {
      if (!tenantId) throw new Error("no se conoce el club");
      const uid = auth.currentUser?.uid;
      if (!uid) throw new Error("no hay sesión iniciada");
      const nombre = file.name || porDefecto;
      const limpio = String(nombre).replace(/[^\w.\-]+/g, "_");
      const path = `clubes/${tenantId}/finanzas/tickets/${uid}/${Date.now()}_${limpio}`;
      await uploadBytes(ref(storage, path), file, file.type ? { contentType: file.type } : undefined);
      return { ticket: { path, nombre, tipo: file.type || "", tam: file.size || 0 } };
    } catch (e) {
      console.warn("No se pudo guardar el archivo en Storage:", e);
      return { ticketError: e?.message || String(e) };
    }
  };

  const hoy = () => new Date().toISOString().slice(0, 10);

  const procesarImagen = async (file) => {
    setError("");
    setImagen(URL.createObjectURL(file));
    setProcesando(true);
    // Primero se guarda el archivo (aunque luego falle la lectura automática).
    const guardado = await guardarArchivo(file, "ticket.jpg");
    try {
      const imageBase64 = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result.split(",")[1]);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });
      const { data } = await leerTicketIA({ imageBase64, mediaType: file.type || "image/jpeg" });
      onDetectado({
        amount: data?.importeTotal != null ? String(data.importeTotal) : "",
        date: data?.fecha || hoy(),
        description: (data?.descripcion || data?.proveedor || "").slice(0, 60),
        proveedor: (data?.proveedor || "").slice(0, 80),
        tipo: data?.tipo === "ingreso" ? "income" : "expense",
        categoriaSugerida: data?.categoriaSugerida || "",
        ivaPct: data?.ivaPct != null ? String(data.ivaPct) : "",
        base: data?.importeBase != null ? String(data.importeBase) : "",
        ...guardado,
      });
    } catch (e) {
      console.warn("Error leyendo imagen con IA:", e);
      onDetectado({ amount: "", date: hoy(), description: "", aviso: "No se ha podido leer el ticket automáticamente. Rellena los datos a mano.", ...guardado });
    }
  };

  // Lee el texto "de verdad" incrustado en un PDF digital (facturas
  // generadas por ordenador). Si el PDF es un escaneo sin texto
  // (foto metida dentro de un PDF), el archivo se guarda igualmente y los datos se rellenan a mano.
  const procesarPdf = async (file) => {
    setError("");
    setNombrePdf(file.name);
    setProcesando(true);
    const guardado = await guardarArchivo(file, "factura.pdf");
    try {
      const pdfjsLib = await import("pdfjs-dist/build/pdf");
      pdfjsLib.GlobalWorkerOptions.workerSrc = new URL("pdfjs-dist/build/pdf.worker.min.mjs", import.meta.url).toString();
      const buffer = await file.arrayBuffer();
      const pdf = await pdfjsLib.getDocument({ data: buffer }).promise;
      let texto = "";
      for (let i = 1; i <= Math.min(pdf.numPages, 5); i++) {
        const pagina = await pdf.getPage(i);
        const contenido = await pagina.getTextContent();
        texto += contenido.items.map((it) => it.str).join(" ") + "\n";
      }
      if (texto.trim().length < 15) {
        onDetectado({ amount: "", date: hoy(), description: "", aviso: "Este PDF parece un escaneo (sin texto real dentro). Rellena los datos a mano o prueba a subir una foto.", ...guardado });
        return;
      }
      onDetectado({ ...extraerDatosTicket(texto), ...guardado });
    } catch (e) {
      console.warn("Error leyendo PDF:", e);
      onDetectado({ amount: "", date: hoy(), description: "", aviso: "No se ha podido leer el PDF automáticamente. Rellena los datos a mano.", ...guardado });
    }
  };

  const procesarArchivo = (file) => {
    if (!file) return;
    if (file.type === "application/pdf" || file.name?.toLowerCase().endsWith(".pdf")) {
      procesarPdf(file);
    } else {
      procesarImagen(file);
    }
  };

  return (
    <div
      style={{
        position: "fixed", inset: 0, background: "rgba(28,43,34,0.35)",
        display: "flex", alignItems: "center", justifyContent: "center", zIndex: 60,
      }}
    >
      <div
        className="shadow-lg rounded-2xl"
        style={{ background: theme.surface, padding: 24, width: 380, maxWidth: "90vw" }}
      >
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
          <div style={{ fontWeight: 700, fontSize: 16, color: theme.ink }}>Escanear ticket o factura</div>
          <button type="button" onClick={onClose} style={{ border: "none", background: "none", cursor: "pointer" }}>
            <X size={18} />
          </button>
        </div>

        {!imagen && !nombrePdf && (
          <label
            style={{
              display: "flex", flexDirection: "column", alignItems: "center", gap: 10,
              border: `2px dashed ${theme.border}`, borderRadius: 12, padding: "36px 16px",
              cursor: "pointer", textAlign: "center",
            }}
          >
            <Camera size={30} color={theme.accent} />
            <span style={{ fontSize: 13, color: theme.inkSoft }}>
              Foto/imagen de un ticket, o PDF de una factura digital
            </span>
            <input
              type="file"
              accept="image/*,application/pdf"
              capture="environment"
              style={{ display: "none" }}
              onChange={(e) => procesarArchivo(e.target.files?.[0])}
            />
          </label>
        )}

        {imagen && (
          <div style={{ textAlign: "center" }}>
            <img
              src={imagen} alt="Ticket"
              style={{ maxWidth: "100%", maxHeight: 220, borderRadius: 8, marginBottom: 12, objectFit: "contain" }}
            />
            {procesando && (
              <div style={{ fontSize: 13, color: theme.inkSoft }}>Leyendo el ticket…</div>
            )}
          </div>
        )}

        {nombrePdf && (
          <div style={{ textAlign: "center", padding: "20px 0" }}>
            <FileText size={30} color={theme.accent} style={{ margin: "0 auto 10px" }} />
            <div style={{ fontSize: 13, color: theme.ink, fontWeight: 600, marginBottom: 4 }}>{nombrePdf}</div>
            {procesando && (
              <div style={{ fontSize: 13, color: theme.inkSoft }}>Leyendo la factura…</div>
            )}
          </div>
        )}

        {error && (
          <div style={{ fontSize: 13, color: theme.danger, marginTop: 10 }}>{error}</div>
        )}
      </div>
    </div>
  );
}


/* ------------------------- Importar Excel/CSV en bloque -------------------------- */

// Quita acentos y pasa a minúsculas, para reconocer cabeceras de
// columna aunque estén escritas de formas distintas (Fecha/fecha/Date…).
const normalizarClave = (s) =>
  String(s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();

function normalizarFilaExcel(filaOriginal, categoriasDisponibles) {
  const fila = {};
  Object.entries(filaOriginal).forEach(([k, v]) => { fila[normalizarClave(k)] = v; });

  const rawFecha = fila["fecha"] ?? fila["date"] ?? "";
  let fecha = new Date().toISOString().slice(0, 10);
  if (rawFecha instanceof Date && !isNaN(rawFecha)) {
    fecha = rawFecha.toISOString().slice(0, 10);
  } else if (rawFecha) {
    const s = String(rawFecha).trim();
    const mDMY = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);
    if (mDMY) {
      let [, d, m, y] = mDMY; if (y.length === 2) y = "20" + y;
      fecha = `${y}-${m.padStart(2, "0")}-${d.padStart(2, "0")}`;
    } else if (!isNaN(new Date(s))) {
      fecha = new Date(s).toISOString().slice(0, 10);
    }
  }

  const rawTipo = normalizarClave(fila["tipo"] ?? fila["type"] ?? "");
  let importeRaw = fila["importe"] ?? fila["amount"] ?? fila["cantidad"] ?? fila["total"] ?? "0";
  importeRaw = String(importeRaw).replace(/[€\s]/g, "").replace(/\.(?=\d{3}(?:\D|$))/g, "").replace(",", ".");
  let importe = parseFloat(importeRaw) || 0;

  let tipo = rawTipo.includes("ingres") || rawTipo.includes("income") ? "income"
    : rawTipo.includes("gasto") || rawTipo.includes("expense") ? "expense"
    : importe < 0 ? "expense" : "income";
  importe = Math.abs(importe);

  const categoria = String(fila["categoria"] ?? fila["category"] ?? fila["partida"] ?? "").trim()
    || (tipo === "income" ? categoriasDisponibles.ingresos[0] : categoriasDisponibles.gastos[0]);
  const subcategoria = String(fila["subcategoria"] ?? fila["subcategory"] ?? fila["subfamilia"] ?? "").trim();
  const descripcion = String(fila["descripcion"] ?? fila["concepto"] ?? fila["description"] ?? "").trim();

  return { incluir: true, date: fecha, type: tipo, category: categoria, subcategory: subcategoria, description: descripcion, amount: importe.toFixed(2) };
}

function descargarPlantilla() {
  const csv = "Fecha,Tipo,Categoría,Subcategoría,Descripción,Importe\n2026-01-15,Gasto,Electricidad,,Recibo luz enero,145.30\n2026-01-20,Ingreso,Greenfees,GFs no socios,Greenfees enero,890.00\n";
  const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = "plantilla_transacciones_golfb.csv"; a.click();
  URL.revokeObjectURL(url);
}

function ImportarExcelModal({ onClose, onAdd, categorias }) {
  const [filas, setFilas] = useState(null);
  const [cargando, setCargando] = useState(false);
  const [error, setError] = useState("");
  const [importando, setImportando] = useState(false);
  const [progreso, setProgreso] = useState(0);
  const [hecho, setHecho] = useState(false);

  const cargarArchivo = async (file) => {
    if (!file) return;
    setError(""); setCargando(true); setFilas(null);
    try {
      const XLSX = await import("xlsx");
      const buffer = await file.arrayBuffer();
      const wb = XLSX.read(buffer, { type: "array", cellDates: true });
      const hoja = wb.Sheets[wb.SheetNames[0]];
      const filasCrudas = XLSX.utils.sheet_to_json(hoja, { defval: "" });
      if (filasCrudas.length === 0) {
        setError("No se han encontrado filas con datos en el archivo.");
      } else {
        setFilas(filasCrudas.map((f) => normalizarFilaExcel(f, categorias)));
      }
    } catch (e) {
      console.warn("Error leyendo Excel:", e);
      setError("No se ha podido leer el archivo. Comprueba que sea un .xlsx, .xls o .csv válido.");
    }
    setCargando(false);
  };

  const actualizarFila = (i, campo, valor) => {
    setFilas(filas.map((f, idx) => (idx === i ? { ...f, [campo]: valor } : f)));
  };

  const seleccionadas = (filas || []).filter((f) => f.incluir);

  const importar = async () => {
    setImportando(true); setProgreso(0);
    for (let i = 0; i < seleccionadas.length; i++) {
      const f = seleccionadas[i];
      await onAdd({
        type: f.type, category: f.category, subcategory: f.subcategory || "", description: f.description,
        amount: Number(f.amount).toFixed(2), date: new Date(f.date).toISOString(),
        activity: "", iva_type: "", base_amount: null, irpf_deductible: "no",
      });
      setProgreso(i + 1);
    }
    setImportando(false);
    setHecho(true);
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(28,43,34,0.35)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 60 }}>
      <div style={{ background: theme.surface, borderRadius: 16, padding: 24, width: 720, maxWidth: "94vw", maxHeight: "88vh", display: "flex", flexDirection: "column" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
          <div style={{ fontWeight: 700, fontSize: 16, color: theme.ink }}>Importar transacciones desde Excel/CSV</div>
          <button onClick={onClose} style={{ border: "none", background: "none", cursor: "pointer" }}><X size={18} /></button>
        </div>

        {!filas && (
          <>
            <div style={{ fontSize: 13, color: theme.inkSoft, marginBottom: 14 }}>
              Sube un archivo con columnas <b>Fecha, Tipo (Ingreso/Gasto), Categoría, Subcategoría (opcional), Descripción, Importe</b> — el orden no importa, y reconoce nombres en español o inglés.{" "}
              <button onClick={descargarPlantilla} style={{ border: "none", background: "none", color: theme.accent, fontWeight: 700, cursor: "pointer", padding: 0, textDecoration: "underline" }}>
                Descargar plantilla de ejemplo
              </button>
            </div>
            <label
              style={{
                display: "flex", flexDirection: "column", alignItems: "center", gap: 10,
                border: `2px dashed ${theme.border}`, borderRadius: 12, padding: "40px 16px",
                cursor: "pointer", textAlign: "center",
              }}
            >
              <Upload size={30} color={theme.accent} />
              <span style={{ fontSize: 13, color: theme.inkSoft }}>
                {cargando ? "Leyendo archivo…" : "Haz clic para elegir tu archivo .xlsx, .xls o .csv"}
              </span>
              <input type="file" accept=".xlsx,.xls,.csv" style={{ display: "none" }}
                onChange={(e) => cargarArchivo(e.target.files?.[0])} />
            </label>
            {error && <div style={{ fontSize: 13, color: theme.danger, marginTop: 10 }}>{error}</div>}
          </>
        )}

        {filas && !hecho && (
          <>
            <div style={{ fontSize: 13, color: theme.inkSoft, marginBottom: 10 }}>
              Revisa los datos detectados — desmarca las filas que no quieras importar, o corrige lo que haga falta. Se han encontrado <b>{filas.length}</b> filas.
            </div>
            <div style={{ flex: 1, overflow: "auto", border: `1px solid ${theme.border}`, borderRadius: 10 }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
                <thead style={{ position: "sticky", top: 0, background: theme.bg }}>
                  <tr>
                    {["", "Fecha", "Tipo", "Categoría", "Subcategoría", "Descripción", "Importe"].map((h) => (
                      <th key={h} style={{ textAlign: "left", padding: "8px 10px", color: theme.inkSoft, fontWeight: 700 }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {filas.map((f, i) => (
                    <tr key={i} style={{ borderTop: `1px solid ${theme.border}`, opacity: f.incluir ? 1 : 0.4 }}>
                      <td style={{ padding: "6px 10px" }}>
                        <input type="checkbox" checked={f.incluir} onChange={(e) => actualizarFila(i, "incluir", e.target.checked)} />
                      </td>
                      <td style={{ padding: "6px 10px" }}>
                        <input type="date" value={f.date} onChange={(e) => actualizarFila(i, "date", e.target.value)}
                          style={{ border: `1px solid ${theme.border}`, borderRadius: 6, padding: "4px 6px", fontSize: 12, width: 128 }} />
                      </td>
                      <td style={{ padding: "6px 10px" }}>
                        <select value={f.type} onChange={(e) => actualizarFila(i, "type", e.target.value)}
                          style={{ border: `1px solid ${theme.border}`, borderRadius: 6, padding: "4px 6px", fontSize: 12 }}>
                          <option value="income">Ingreso</option>
                          <option value="expense">Gasto</option>
                        </select>
                      </td>
                      <td style={{ padding: "6px 10px" }}>
                        <input value={f.category} onChange={(e) => actualizarFila(i, "category", e.target.value)}
                          style={{ border: `1px solid ${theme.border}`, borderRadius: 6, padding: "4px 6px", fontSize: 12, width: 130 }} />
                      </td>
                      <td style={{ padding: "6px 10px" }}>
                        <input value={f.subcategory} onChange={(e) => actualizarFila(i, "subcategory", e.target.value)}
                          style={{ border: `1px solid ${theme.border}`, borderRadius: 6, padding: "4px 6px", fontSize: 12, width: 130 }} />
                      </td>
                      <td style={{ padding: "6px 10px" }}>
                        <input value={f.description} onChange={(e) => actualizarFila(i, "description", e.target.value)}
                          style={{ border: `1px solid ${theme.border}`, borderRadius: 6, padding: "4px 6px", fontSize: 12, width: 160 }} />
                      </td>
                      <td style={{ padding: "6px 10px" }}>
                        <input type="number" step="0.01" value={f.amount} onChange={(e) => actualizarFila(i, "amount", e.target.value)}
                          style={{ border: `1px solid ${theme.border}`, borderRadius: 6, padding: "4px 6px", fontSize: 12, width: 80 }} />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 14 }}>
              <span style={{ fontSize: 13, color: theme.inkSoft }}>
                {importando ? `Importando ${progreso} de ${seleccionadas.length}…` : `${seleccionadas.length} de ${filas.length} filas seleccionadas`}
              </span>
              <button
                onClick={importar}
                disabled={seleccionadas.length === 0 || importando}
                style={{
                  padding: "10px 20px", borderRadius: 10, border: "none",
                  background: seleccionadas.length === 0 || importando ? theme.border : theme.accent,
                  color: "#fff", fontWeight: 700, cursor: seleccionadas.length === 0 || importando ? "default" : "pointer",
                }}
              >
                {importando ? "Importando…" : `Importar ${seleccionadas.length} transacciones`}
              </button>
            </div>
          </>
        )}

        {hecho && (
          <div style={{ textAlign: "center", padding: "30px 0" }}>
            <Check size={40} color={theme.success} style={{ margin: "0 auto 12px" }} />
            <div style={{ fontWeight: 700, color: theme.ink, marginBottom: 6 }}>¡Importación completada!</div>
            <div style={{ fontSize: 13, color: theme.inkSoft, marginBottom: 18 }}>
              Se han añadido {seleccionadas.length} transacciones nuevas.
            </div>
            <button onClick={onClose} style={{ padding: "10px 22px", borderRadius: 10, border: "none", background: theme.accent, color: "#fff", fontWeight: 700, cursor: "pointer" }}>
              Cerrar
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

function TransaccionForm({ onClose, onSave, onSaveVarios, onUpdate, onUpdateVarios, initial, categorias, destinoInicial, editando }) {
  // Categoría sugerida por la IA: se usa la existente que coincida (sin tildes ni mayúsculas); si no hay, la propia sugerencia.
  const tipoInicial = editando ? (editando.type === "income" ? "income" : "expense") : initial?.tipo === "income" ? "income" : "expense";
  const categoriaInicial = (() => {
    const sug = initial?.categoriaSugerida;
    if (!sug) return "";
    const lista = (tipoInicial === "income" ? categorias?.ingresos : categorias?.gastos) || [];
    return lista.find((c) => normTx(c) === normTx(sug)) || sug;
  })();
  const fechaOriginal = editando ? gzIso(aFecha(editando.date)) : "";
  const [form, setForm] = useState(
    editando
      ? {
          type: tipoInicial,
          category: editando.category || "",
          subcategory: editando.subcategory || "",
          proveedor: editando.proveedor || "",
          description: editando.description || "",
          amount: editando.amount != null ? String(editando.amount) : "",
          date: fechaOriginal,
          activity: editando.activity || "",
          iva_type: editando.iva_type || "",
          base_amount: editando.base_amount != null && editando.base_amount !== "" ? String(editando.base_amount) : "",
          irpf_deductible: editando.irpf_deductible || "no",
          metodo_pago: editando.metodo_pago || "",
          destino: destinoDeTx(editando) === "sin" ? (destinoInicial || "club") : destinoDeTx(editando),
        }
      : {
          type: tipoInicial,
          category: categoriaInicial,
          subcategory: "",
          proveedor: initial?.proveedor || "",
          description: initial?.description || "",
          amount: initial?.amount || "",
          date: initial?.date || new Date().toISOString().slice(0, 10),
          activity: "",
          iva_type: initial?.ivaPct || "",
          base_amount: initial?.base || (initial?.ivaPct && initial?.amount ? (Number(initial.amount) / (1 + Number(initial.ivaPct) / 100)).toFixed(2) : ""),
          irpf_deductible: "no",
          metodo_pago: initial?.metodo_pago || "",
          destino: initial?.entidad ? (initial.entidad === "jmcf" ? (initial.negocio || "proshop") : initial.entidad) : (destinoInicial || "club"),
        }
  );
  // Reparto de un ticket compartido entre varias economías / categorías
  const [reparto, setReparto] = useState(false);
  const [lineas, setLineas] = useState([
    { destino: form.destino, category: "", amount: "" },
    { destino: form.destino === "club" ? "proshop" : "club", category: "", amount: "" },
  ]);
  const totalTicket = Number(form.amount) || 0;
  const sumaOtras = lineas.slice(0, -1).reduce((s, l) => s + (Number(l.amount) || 0), 0);
  const resto = Math.round((totalTicket - sumaOtras) * 100) / 100;
  const setLinea = (i, k, v) => setLineas(lineas.map((l, j) => (j === i ? { ...l, [k]: v } : l)));

  const set = (k) => (e) => setForm({ ...form, [k]: e.target.value });

  const submit = (e) => {
    e.preventDefault();
    if (!form.amount) return;
    const iso = new Date(form.date).toISOString();
    const base = form.base_amount ? Number(form.base_amount) : null;
    const ivaPct = form.iva_type ? Number(form.iva_type) : null;

    if (reparto) {
      if (!(totalTicket > 0)) { window.alert("Pon primero el importe total del ticket."); return; }
      const gid = `gt-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
      const datas = lineas.map((l, i) => {
        const imp = i === lineas.length - 1 ? resto : Number(l.amount) || 0;
        const baseL = base != null ? (base * imp) / totalTicket : null;
        return {
          type: form.type,
          category: l.category.trim() || form.category.trim(),
          subcategory: form.subcategory,
          proveedor: form.proveedor,
          description: form.description,
          activity: form.activity,
          iva_type: form.iva_type,
          irpf_deductible: form.irpf_deductible,
          date: iso,
          amount: imp.toFixed(2),
          base_amount: baseL != null ? baseL.toFixed(2) : null,
          iva_amount: baseL != null && ivaPct != null ? (baseL * (ivaPct / 100)).toFixed(2) : null,
          ...destinoAEnt(l.destino),
          metodo_pago: l.destino === "club" ? "" : form.metodo_pago || "",
          grupo_ticket: gid,
          importe_ticket: totalTicket.toFixed(2),
        };
      });
      if (datas.some((d) => !(Number(d.amount) > 0))) { window.alert("Todas las líneas deben tener un importe mayor que 0. La última se calcula sola con lo que falta por repartir."); return; }
      if (datas.some((d) => !d.category)) { window.alert("Pon una categoría en cada línea (o una general arriba)."); return; }
      if (editando) { onUpdateVarios && onUpdateVarios(editando.id, datas); return; }
      onSaveVarios && onSaveVarios(datas.map((d) => ({ ...d, ticket_path: initial?.ticket?.path || null, ticket_nombre: initial?.ticket?.nombre || null })));
      return;
    }

    if (!form.category) { window.alert("Elige o escribe una categoría."); return; }
    const comun = {
      ...form,
      ...destinoAEnt(form.destino),
      metodo_pago: form.destino === "club" ? "" : form.metodo_pago || "",
      amount: Number(form.amount).toFixed(2),
      base_amount: form.base_amount ? Number(form.base_amount).toFixed(2) : null,
      iva_amount: form.base_amount && form.iva_type ? (Number(form.base_amount) * (Number(form.iva_type) / 100)).toFixed(2) : null,
    };
    if (editando) {
      const cambios = { ...comun };
      if (form.date === fechaOriginal) delete cambios.date; // no se toca la fecha original si no la has cambiado
      else cambios.date = iso;
      onUpdate && onUpdate(editando.id, cambios);
      return;
    }
    onSave({
      ...comun,
      ticket_path: initial?.ticket?.path || null,
      ticket_nombre: initial?.ticket?.nombre || null,
      date: iso,
    });
  };

  const inputStyle = {
    width: "100%",
    padding: "8px 10px",
    borderRadius: 8,
    border: `1px solid ${theme.border}`,
    fontSize: 14,
    marginTop: 4,
  };
  const label = { fontSize: 12, fontWeight: 600, color: theme.inkSoft };

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(28,43,34,0.35)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 50,
      }}
    >
      <form
        onSubmit={submit}
        className="shadow-lg rounded-2xl"
        style={{ background: theme.surface, padding: 24, width: reparto ? 560 : 420, maxWidth: "95vw", maxHeight: "90vh", overflowY: "auto" }}
      >
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
          <div style={{ fontWeight: 700, fontSize: 16, color: theme.ink }}>{editando ? "Editar transacción" : "Nueva transacción"}</div>
          <button type="button" onClick={onClose} style={{ border: "none", background: "none", cursor: "pointer" }}>
            <X size={18} />
          </button>
        </div>

        {initial && !editando && (
          <div
            style={{
              display: "flex", alignItems: "center", gap: 8, background: theme.accentSoft,
              color: "#8A6A2E", borderRadius: 8, padding: "8px 12px", fontSize: 12.5, marginBottom: 14,
            }}
          >
            <Camera size={14} />
            Datos detectados del ticket — revísalos antes de guardar.
          </div>
        )}
        {initial?.aviso && (
          <div style={{ background: "#FBEAE5", color: theme.danger, borderRadius: 8, padding: "8px 12px", fontSize: 12.5, marginBottom: 10 }}>{initial.aviso}</div>
        )}
        {editando?.ticket_path && (
          <div style={{ background: "#E7F3EB", color: theme.success, borderRadius: 8, padding: "8px 12px", fontSize: 12.5, marginBottom: 10 }}>
            📎 Esta transacción tiene archivo adjunto: se conserva.
          </div>
        )}
        {initial?.ticket && (
          <div style={{ background: "#E7F3EB", color: theme.success, borderRadius: 8, padding: "8px 12px", fontSize: 12.5, marginBottom: 10 }}>
            📎 Archivo guardado: {initial.ticket.nombre}. Quedará enlazado a esta transacción.
          </div>
        )}
        {initial?.ticketError && (
          <div style={{ background: "#FBEAE5", color: theme.danger, borderRadius: 8, padding: "8px 12px", fontSize: 12.5, marginBottom: 10 }}>
            No se ha podido guardar el archivo ({initial.ticketError}). Puedes guardar la transacción igualmente, pero no tendrá archivo enlazado.
          </div>
        )}

        <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
          {["expense", "income"].map((t) => (
            <button
              type="button"
              key={t}
              onClick={() => setForm({ ...form, type: t })}
              style={{
                flex: 1,
                padding: "8px 0",
                borderRadius: 8,
                border: `1px solid ${form.type === t ? theme.accent : theme.border}`,
                background: form.type === t ? theme.accentSoft : "transparent",
                color: form.type === t ? theme.accent : theme.inkSoft,
                fontWeight: 600,
                cursor: "pointer",
              }}
            >
              {t === "expense" ? "Gasto" : "Ingreso"}
            </button>
          ))}
        </div>

        <label style={label}>Categoría</label>
        <input style={inputStyle} value={form.category} onChange={set("category")} list="lista-categorias" placeholder="Elige o escribe una nueva…" />
        <datalist id="lista-categorias">
          {((form.destino === "piso" ? CATEGORIAS_PISO : categorias) || {})[form.type === "income" ? "ingresos" : "gastos"]?.map((c) => <option key={c} value={c} />)}
        </datalist>

        <label style={label}>Subcategoría (opcional)</label>
        <input style={inputStyle} value={form.subcategory} onChange={set("subcategory")} list="lista-subcategorias" placeholder="Ej: Greenfees no socios…" />
        <datalist id="lista-subcategorias">
          {((categorias?.subcategorias || {})[form.category] || []).map((s) => <option key={s} value={s} />)}
        </datalist>

        <label style={label}>Proveedor (opcional)</label>
        <input style={inputStyle} value={form.proveedor} onChange={set("proveedor")} placeholder="Ej: Leroy Merlin" />

        <label style={label}>Descripción</label>
        <input style={inputStyle} value={form.description} onChange={set("description")} />

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          <div>
            <label style={label}>Importe (€)</label>
            <input style={inputStyle} type="number" step="0.01" value={form.amount} onChange={set("amount")} required />
          </div>
          <div>
            <label style={label}>Fecha</label>
            <input style={inputStyle} type="date" value={form.date} onChange={set("date")} />
          </div>
        </div>

        <label style={label}>Actividad (opcional: club / mantenimiento...)</label>
        <input style={inputStyle} value={form.activity} onChange={set("activity")} />

        <label style={label}>¿A qué economía va?</label>
        <select style={inputStyle} value={form.destino} onChange={set("destino")}>
          {DESTINOS.map(([id, n]) => <option key={id} value={id}>{n}</option>)}
        </select>

        {form.destino !== "club" && (
          <>
            <label style={label}>Forma de pago</label>
            <select style={inputStyle} value={form.metodo_pago} onChange={set("metodo_pago")}>
              <option value="">Sin indicar</option>
              {METODOS_PAGO.map((m) => <option key={m} value={m}>{m}</option>)}
            </select>
          </>
        )}

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          <div>
            <label style={label}>Base imponible (opcional)</label>
            <input style={inputStyle} type="number" step="0.01" value={form.base_amount} onChange={set("base_amount")} />
          </div>
          <div>
            <label style={label}>IVA % (opcional)</label>
            <input style={inputStyle} type="number" value={form.iva_type} onChange={set("iva_type")} />
          </div>
        </div>

        <label style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 14, fontSize: 13, fontWeight: 600, color: theme.ink, cursor: "pointer" }}>
          <input type="checkbox" checked={reparto} onChange={(e) => setReparto(e.target.checked)} />
          Ticket compartido: repartirlo entre varias economías o categorías
        </label>
        {reparto && (
          <div style={{ marginTop: 10, border: `1px solid ${theme.border}`, borderRadius: 10, padding: 10, background: "#FBFAF6" }}>
            <div style={{ fontSize: 12.5, color: theme.inkSoft, marginBottom: 8 }}>
              Total del ticket: <b>{fmtEUR(totalTicket)}</b> · la última línea se calcula sola con lo que falta.
            </div>
            {lineas.map((l, i) => {
              const esUltima = i === lineas.length - 1;
              return (
                <div key={i} style={{ display: "grid", gridTemplateColumns: "1.3fr 1.2fr 0.8fr auto", gap: 6, marginBottom: 6, alignItems: "center" }}>
                  <select style={{ ...inputStyle, marginTop: 0 }} value={l.destino} onChange={(e) => setLinea(i, "destino", e.target.value)}>
                    {DESTINOS.map(([id, n]) => <option key={id} value={id}>{n}</option>)}
                  </select>
                  <input style={{ ...inputStyle, marginTop: 0 }} value={l.category} onChange={(e) => setLinea(i, "category", e.target.value)} list="lista-categorias" placeholder={form.category || "Categoría"} />
                  <input
                    style={{ ...inputStyle, marginTop: 0, background: esUltima ? "#F1F1EC" : undefined }}
                    type="number" step="0.01"
                    value={esUltima ? (resto > 0 || sumaOtras > 0 ? resto.toFixed(2) : "") : l.amount}
                    readOnly={esUltima}
                    onChange={(e) => setLinea(i, "amount", e.target.value)}
                    placeholder="€"
                  />
                  {lineas.length > 2 ? (
                    <button type="button" onClick={() => setLineas(lineas.filter((_, j) => j !== i))} style={{ border: "none", background: "none", cursor: "pointer", color: theme.danger }}><X size={14} /></button>
                  ) : <span />}
                </div>
              );
            })}
            <button type="button" onClick={() => setLineas([...lineas.slice(0, -1), { destino: "club", category: "", amount: "" }, lineas[lineas.length - 1]])} style={{ border: `1px dashed ${theme.border}`, background: "transparent", borderRadius: 8, padding: "4px 10px", fontSize: 12.5, cursor: "pointer", color: theme.pine }}>
              + Añadir línea
            </button>
            {resto <= 0 && totalTicket > 0 && <div style={{ color: theme.danger, fontSize: 12.5, marginTop: 6 }}>Las líneas anteriores ya suman el total: baja algún importe.</div>}
            {editando && <div style={{ color: theme.inkSoft, fontSize: 12, marginTop: 6 }}>La transacción actual se queda con la primera línea y se crean las demás; todas comparten el mismo archivo adjunto.</div>}
          </div>
        )}

        <button
          type="submit"
          className="rounded-md"
          style={{
            marginTop: 16,
            width: "100%",
            padding: "10px 0",
            background: theme.accent,
            color: "#fff",
            border: "none",
            fontWeight: 700,
            cursor: "pointer",
          }}
        >
          {reparto ? "Guardar reparto" : editando ? "Guardar cambios" : "Guardar transacción"}
        </button>
      </form>
    </div>
  );
}

/* ============================ IMPORTAR PROVEEDORES (Excel "Control de proveedores") ============================ */
// Lee el Excel de facturas de proveedores y lo guarda como gastos del club (Transacciones), con proveedor, nº de factura y cuenta contable.
// Es idempotente: cada factura tiene un identificador propio, así que volver a importar el Excel acumulado solo añade lo nuevo.
const PROV_FAMILIAS = {
  "INSTALACIONES": "Instalaciones", "SUMINISTROS": "Suministros", "COMPETICIONES": "Competiciones", "MAQUINARIA": "Maquinaria",
  "ADMINISTRACION": "Administración", "MARKETING Y PUBLICIDAD": "Marketing y publicidad", "MANTENIMIENTO": "Mantenimiento",
  "RRHH": "Recursos humanos", "LIMPIEZA E HIGIENE": "Limpieza e higiene", "GASTOS REPRESENTACION": "Gastos de representación",
};
const provLimpio = (s) => String(s ?? "").replace(/\s+/g, " ").trim();
const provNorm = (s) => normTx(provLimpio(s)).replace(/[º°.]/g, "").replace(/\s+/g, " ").trim();
const provTitulo = (s) => { const t = provLimpio(s).toLowerCase(); return t ? t.charAt(0).toUpperCase() + t.slice(1) : ""; };

function provHash(texto) {
  let h1 = 0x811c9dc5, h2 = 0x9747b28c;
  for (let i = 0; i < texto.length; i++) {
    const c = texto.charCodeAt(i);
    h1 ^= c; h1 = Math.imul(h1, 16777619) >>> 0;
    h2 ^= c; h2 = Math.imul(h2, 2246822519) >>> 0;
  }
  return h1.toString(16).padStart(8, "0") + h2.toString(16).padStart(8, "0");
}

function provImporte(v) {
  if (typeof v === "number") return isFinite(v) ? v : null;
  let s = String(v ?? "").replace(/[€\s]/g, "");
  if (!s) return null;
  if (s.includes(",") && s.includes(".")) s = s.replace(/\./g, "").replace(",", ".");
  else if (s.includes(",")) s = s.replace(",", ".");
  const n = parseFloat(s);
  return isFinite(n) && /^-?\d+(\.\d+)?$/.test(s) ? n : null;
}

// Devuelve "AAAA-MM-DD" a partir de una fecha de Excel (Date) o de un texto dd-mm-aaaa / dd/mm/aaaa.
function provFecha(v) {
  if (v instanceof Date && !isNaN(v)) {
    const comoUtc = v.getTime() - v.getTimezoneOffset() * 60000; // lo que se ve en la celda
    const dia = new Date(Math.floor((comoUtc + 43200000) / 86400000) * 86400000);
    return `${dia.getUTCFullYear()}-${String(dia.getUTCMonth() + 1).padStart(2, "0")}-${String(dia.getUTCDate()).padStart(2, "0")}`;
  }
  const m = String(v ?? "").trim().match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$/);
  if (!m) return null;
  const d = Number(m[1]), mes = Number(m[2]);
  if (mes < 1 || mes > 12 || d < 1 || d > 31) return null;
  return `${m[3]}-${String(mes).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

const provSugerirCuenta = (concepto, proveedor) => {
  const t = normTx(`${concepto} ${proveedor}`);
  if (/gasoleo|gasoil|combustible|diesel/.test(t)) return "62800002";
  if (/extintor|prevencion|seguridad/.test(t)) return "62900005";
  if (/vinilo|rotul|senal|publicidad|cartel/.test(t)) return "62700000";
  if (/fito|herbicid|fungicid|semilla|abono|devolucion fac/.test(t)) return "62900010";
  return "62900011";
};

// filas: matriz (hoja leída con header:1). Devuelve { filas:[...], hoja:{anio}, error? }
function provParsear(filas) {
  const idxCab = filas.findIndex((r) => r.some((c) => provNorm(c) === "fecha") && r.some((c) => provNorm(c) === "proveedor"));
  if (idxCab < 0) return { error: "No encuentro la cabecera (FECHA, PROVEEDOR, IMPORTE…). ¿Es el Excel de control de proveedores?" };
  const cab = filas[idxCab].map(provNorm);
  const col = (...nombres) => cab.findIndex((h) => nombres.some((n) => h === n || h.startsWith(n)));
  const c = {
    fecha: col("fecha"), prov: col("proveedor"), conc: col("concepto"), imp: col("importe"),
    sub: col("subfamilia"), fam: col("familia"), cta: col("n cuenta", "numero cuenta", "cuenta"), fac: col("n factura", "numero factura", "factura"),
  };
  if (c.fecha < 0 || c.prov < 0 || c.imp < 0) return { error: "Faltan columnas obligatorias (FECHA, PROVEEDOR, IMPORTE)." };
  const items = [];
  filas.slice(idxCab + 1).forEach((r, i) => {
    const fecha = provFecha(r[c.fecha]);
    const importe = provImporte(r[c.imp]);
    const proveedor = provLimpio(r[c.prov]);
    if (!fecha || importe === null || !proveedor) return;
    const ctaCruda = c.cta >= 0 ? provLimpio(r[c.cta]) : "";
    const cuenta = /^\d{8}$/.test(ctaCruda) ? ctaCruda : "";
    items.push({
      fila: idxCab + 2 + i, fecha, anio: Number(fecha.slice(0, 4)), proveedor,
      concepto: c.conc >= 0 ? provLimpio(r[c.conc]) : "", importe: Math.round(importe * 100) / 100,
      familia: c.fam >= 0 ? provLimpio(r[c.fam]) : "", subfamilia: c.sub >= 0 ? provLimpio(r[c.sub]) : "",
      cuenta, factura: c.fac >= 0 ? provLimpio(r[c.fac]) : "",
    });
  });
  if (!items.length) return { error: "No he encontrado facturas con fecha e importe válidos." };
  // Año de la hoja = el año más frecuente
  const cont = {};
  items.forEach((x) => { cont[x.anio] = (cont[x.anio] || 0) + 1; });
  const anioHoja = Number(Object.entries(cont).sort((a, b) => b[1] - a[1])[0][0]);
  // Cuenta -> familia/subfamilia más habitual (para clasificar las filas sin cuenta cuando se les asigne una)
  const mapaCuenta = {};
  items.forEach((x) => {
    if (!x.cuenta || !x.familia || x.familia === "#N/A") return;
    const k = x.cuenta; const m = (mapaCuenta[k] = mapaCuenta[k] || {});
    const fk = `${provNorm(x.familia)}|${provLimpio(x.subfamilia)}`; m[fk] = (m[fk] || 0) + 1;
  });
  const famDeCuenta = (cta) => {
    const m = mapaCuenta[cta]; if (!m) return null;
    const [fk] = Object.entries(m).sort((a, b) => b[1] - a[1])[0];
    const [f, s] = fk.split("|"); return { familia: f.toUpperCase(), subfamilia: s };
  };
  // Duplicados y su identificador estable
  const vistos = {}, vistosCompleto = {};
  items.forEach((x) => {
    const clave = `${x.fecha}|${provNorm(x.proveedor)}|${provNorm(x.factura)}|${x.importe.toFixed(2)}`;
    vistos[clave] = (vistos[clave] || 0) + 1;
    x.duplicadoDe = vistos[clave] > 1 ? vistos[clave] : 0; // 0 = primera aparición
    const completa = `${clave}|${provNorm(x.concepto)}`;
    vistosCompleto[completa] = (vistosCompleto[completa] || 0) + 1;
    x.id = "prov-" + provHash(`${completa}|${vistosCompleto[completa]}`);
    x.fueraAnio = x.anio !== anioHoja;
    // Fecha posterior a hoy: casi siempre es día y mes cambiados (01-12-2026 en vez de 12-01-2026). Se propone la corregida.
    const hoyIso = new Date().toISOString().slice(0, 10);
    if (x.fecha > hoyIso) {
      x.fechaOriginal = x.fecha;
      const [yy, mm, dd] = x.fecha.split("-");
      const cambiada = `${yy}-${dd}-${mm}`;
      if (Number(dd) <= 12 && cambiada <= hoyIso) { x.fecha = cambiada; x.fechaSugerida = true; }
      x.fechaFutura = true;
    }
    x.sinCuentaOriginal = !x.cuenta;
    if (!x.cuenta) { x.cuenta = provSugerirCuenta(x.concepto, x.proveedor); x.cuentaSugerida = true; }
    const fd = famDeCuenta(x.cuenta);
    if (!x.familia || x.familia === "#N/A") { if (fd) { x.familia = fd.familia; x.subfamilia = fd.subfamilia; } else x.familia = ""; }
    x.incluir = !x.duplicadoDe && !x.fueraAnio;
  });
  return { filas: items, anioHoja, mapaCuenta: Object.fromEntries(Object.keys(mapaCuenta).map((k) => [k, famDeCuenta(k)])) };
}

function provATransaccion(x, mapaCuenta) {
  // si el usuario cambió la cuenta de una fila sin cuenta, se reclasifica según esa cuenta
  let familia = x.familia, sub = x.subfamilia;
  if (x.sinCuentaOriginal && mapaCuenta[x.cuenta]) { familia = mapaCuenta[x.cuenta].familia; sub = mapaCuenta[x.cuenta].subfamilia; }
  const famKey = provLimpio(familia).toUpperCase();
  return {
    type: "expense",
    category: PROV_FAMILIAS[famKey] || provTitulo(familia) || "Sin clasificar",
    subcategory: provTitulo(sub),
    description: x.concepto,
    proveedor: x.proveedor,
    amount: x.importe.toFixed(2),
    date: new Date(x.fecha).toISOString(),
    activity: "",
    iva_type: "",
    base_amount: null,
    iva_amount: null,
    irpf_deductible: "no",
    origen: "proveedores",
    cuenta: x.cuenta,
    num_factura: x.factura || "",
  };
}

function ImportarProveedoresModal({ onClose, tenantId, transacciones }) {
  const [archivo, setArchivo] = useState("");
  const [items, setItems] = useState(null);
  const [mapaCuenta, setMapaCuenta] = useState({});
  const [anioHoja, setAnioHoja] = useState(null);
  const [error, setError] = useState("");
  const [leyendo, setLeyendo] = useState(false);
  const [progreso, setProgreso] = useState(null);
  const [hecho, setHecho] = useState(null);

  const cuentasGasto = useMemo(
    () => Object.keys(PYG_NOMBRES).filter((c) => /^6/.test(c)).sort().map((c) => [c, `${c} · ${PYG_NOMBRES[c]}`]),
    []
  );
  const existentes = useMemo(() => new Map(transacciones.map((t) => [t.id, t])), [transacciones]);

  const leer = async (file) => {
    if (!file) return;
    setError(""); setLeyendo(true); setItems(null); setHecho(null);
    try {
      const XLSX = await import("xlsx");
      const wb = XLSX.read(await file.arrayBuffer(), { type: "array", cellDates: true });
      // hoja con las facturas: la primera que tenga cabecera FECHA + PROVEEDOR
      let res = null;
      for (const nombre of wb.SheetNames) {
        const filas = XLSX.utils.sheet_to_json(wb.Sheets[nombre], { header: 1, defval: "", raw: true });
        const r = provParsear(filas);
        if (!r.error) { res = r; break; }
        if (!res) res = r;
      }
      if (res.error) { setError(res.error); }
      else { setItems(res.filas); setMapaCuenta(res.mapaCuenta); setAnioHoja(res.anioHoja); setArchivo(file.name); }
    } catch (e) {
      setError("No se ha podido leer el archivo. Comprueba que sea un .xlsx válido.");
    }
    setLeyendo(false);
  };

  const cambiar = (id, campos) => setItems((arr) => arr.map((x) => (x.id === id ? { ...x, ...campos } : x)));

  const aImportar = (items || []).filter((x) => x.incluir);
  const total = aImportar.reduce((s, x) => s + x.importe, 0);
  const estado = (x) => {
    const e = existentes.get(x.id);
    if (!e) return "nueva";
    const t = provATransaccion(x, mapaCuenta);
    return String(e.amount) === t.amount && e.cuenta === t.cuenta && e.category === t.category && e.description === t.description && e.proveedor === t.proveedor ? "igual" : "cambiada";
  };
  const resumen = { nueva: 0, igual: 0, cambiada: 0 };
  aImportar.forEach((x) => { resumen[estado(x)] += 1; });
  const dups = (items || []).filter((x) => x.duplicadoDe);
  const sinCuenta = (items || []).filter((x) => x.sinCuentaOriginal && !x.fueraAnio);
  const fuera = (items || []).filter((x) => x.fueraAnio);
  const futuras = (items || []).filter((x) => x.fechaFutura);

  const importar = async () => {
    setError("");
    const lista = aImportar.filter((x) => estado(x) !== "igual");
    setProgreso({ hechos: 0, total: lista.length });
    try {
      for (let i = 0; i < lista.length; i += 20) {
        const lote = lista.slice(i, i + 20);
        await Promise.all(lote.map((x) => {
          const datos = provATransaccion(x, mapaCuenta);
          const nueva = !existentes.has(x.id);
          return setDoc(
            doc(db, `clubes/${tenantId}/finanzas_transacciones`, x.id),
            nueva ? { ...datos, entidad: "club", created_at: serverTimestamp() } : datos,
            { merge: true }
          );
        }));
        setProgreso({ hechos: Math.min(i + 20, lista.length), total: lista.length });
      }
      setHecho({ nuevas: resumen.nueva, cambiadas: resumen.cambiada, iguales: resumen.igual });
    } catch (e) {
      setError("No se ha podido guardar: " + (e?.message || e));
    }
    setProgreso(null);
  };

  const th = { textAlign: "left", padding: "6px 8px", fontSize: 11.5, color: theme.inkSoft, borderBottom: `1px solid ${theme.border}` };
  const td = { padding: "6px 8px", fontSize: 12.5, color: theme.ink, borderBottom: `1px solid ${theme.border}`, verticalAlign: "top" };
  const bloque = (titulo, ayuda, filas) => filas.length > 0 && (
    <div style={{ marginTop: 14 }}>
      <div style={{ fontWeight: 700, fontSize: 13.5, color: theme.ink }}>{titulo} ({filas.length})</div>
      <div style={{ fontSize: 12, color: theme.inkSoft, margin: "2px 0 6px" }}>{ayuda}</div>
      <div style={{ border: `1px solid ${theme.border}`, borderRadius: 8, maxHeight: 220, overflow: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <tbody>{filas}</tbody>
        </table>
      </div>
    </div>
  );

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(28,43,34,0.35)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 60 }}>
      <div className="shadow-lg rounded-2xl" style={{ background: theme.surface, padding: 24, width: 760, maxWidth: "94vw", maxHeight: "90vh", overflow: "auto" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
          <div style={{ fontWeight: 700, fontSize: 16, color: theme.ink }}>Importar facturas de proveedores</div>
          <button type="button" onClick={onClose} style={{ border: "none", background: "none", cursor: "pointer" }}><X size={18} /></button>
        </div>

        {hecho ? (
          <div>
            <div style={{ background: "#E7F3EB", color: theme.success, padding: 12, borderRadius: 10, fontSize: 14 }}>
              Importación terminada: {hecho.nuevas} facturas nuevas, {hecho.cambiadas} actualizadas y {hecho.iguales} que ya estaban.
            </div>
            <div style={{ textAlign: "right", marginTop: 14 }}>
              <button onClick={onClose} style={{ background: theme.accent, color: "#fff", border: "none", borderRadius: 8, padding: "9px 16px", fontWeight: 600, cursor: "pointer" }}>Cerrar</button>
            </div>
          </div>
        ) : !items ? (
          <label style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 10, border: `2px dashed ${theme.border}`, borderRadius: 12, padding: "36px 16px", cursor: "pointer", textAlign: "center" }}>
            <Upload size={30} color={theme.accent} />
            <span style={{ fontSize: 13, color: theme.inkSoft }}>
              {leyendo ? "Leyendo el Excel…" : "Excel «Control de proveedores» (.xlsx). Puedes volver a importar el archivo completo: solo se añade lo nuevo."}
            </span>
            <input type="file" accept=".xlsx,.xls" style={{ display: "none" }} onChange={(e) => leer(e.target.files?.[0])} />
          </label>
        ) : (
          <div>
            <div style={{ fontSize: 13, color: theme.inkSoft }}>{archivo} · hoja de {anioHoja} · {items.length} facturas leídas</div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))", gap: 10, margin: "10px 0" }}>
              {[["A importar", `${aImportar.length} · ${fmtEUR(total)}`], ["Nuevas", resumen.nueva], ["Ya existentes", resumen.igual], ["Actualizadas", resumen.cambiada]].map(([t, v]) => (
                <div key={t} style={{ background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 10, padding: "8px 10px" }}>
                  <div style={{ fontSize: 11.5, color: theme.inkSoft }}>{t}</div>
                  <div style={{ fontSize: 15, fontWeight: 700, color: theme.ink }}>{v}</div>
                </div>
              ))}
            </div>

            {bloque("Posibles duplicados", "Mismo proveedor, nº de factura, importe y fecha. Por defecto solo se importa la primera; marca la casilla si es una factura distinta.",
              dups.map((x) => (
                <tr key={x.id}>
                  <td style={td}><input type="checkbox" checked={x.incluir} onChange={(e) => cambiar(x.id, { incluir: e.target.checked })} /></td>
                  <td style={td}>{x.fecha}</td><td style={td}>{x.proveedor}</td><td style={td}>{x.concepto}<div style={{ color: theme.inkSoft }}>{x.factura}</div></td>
                  <td style={{ ...td, textAlign: "right", whiteSpace: "nowrap" }}>{fmtEUR(x.importe)}</td>
                </tr>
              )))}

            {bloque("Sin cuenta contable", "Estos proveedores no están en tu tabla de proveedores. Te propongo una cuenta; cámbiala si no es la correcta.",
              sinCuenta.map((x) => (
                <tr key={x.id}>
                  <td style={td}>{x.fecha}</td><td style={td}>{x.proveedor}<div style={{ color: theme.inkSoft }}>{x.concepto}</div></td>
                  <td style={{ ...td, textAlign: "right", whiteSpace: "nowrap" }}>{fmtEUR(x.importe)}</td>
                  <td style={td}>
                    <select value={x.cuenta} onChange={(e) => cambiar(x.id, { cuenta: e.target.value, cuentaSugerida: false })} style={{ padding: "4px 6px", borderRadius: 6, border: `1px solid ${theme.border}`, fontSize: 12, maxWidth: 230 }}>
                      {cuentasGasto.map(([c, t]) => <option key={c} value={c}>{t}</option>)}
                    </select>
                  </td>
                </tr>
              )))}

            {bloque("Fecha posterior a hoy", "La fecha del Excel es futura, probablemente con día y mes cambiados. Te propongo la fecha corregida; edítala si no es la correcta.",
              futuras.map((x) => (
                <tr key={x.id}>
                  <td style={td}>
                    <input type="date" value={x.fecha} onChange={(e) => e.target.value && cambiar(x.id, { fecha: e.target.value, anio: Number(e.target.value.slice(0, 4)) })} style={{ padding: "3px 6px", borderRadius: 6, border: `1px solid ${theme.border}`, fontSize: 12 }} />
                    <div style={{ color: theme.inkSoft, fontSize: 11.5 }}>Excel: {x.fechaOriginal}</div>
                  </td>
                  <td style={td}>{x.proveedor}<div style={{ color: theme.inkSoft }}>{x.concepto}</div></td>
                  <td style={{ ...td, textAlign: "right", whiteSpace: "nowrap" }}>{fmtEUR(x.importe)}</td>
                </tr>
              )))}

            {bloque("Fuera del año de la hoja", `Facturas con fecha distinta de ${anioHoja}. Por defecto no se importan.`,
              fuera.map((x) => (
                <tr key={x.id}>
                  <td style={td}><input type="checkbox" checked={x.incluir} onChange={(e) => cambiar(x.id, { incluir: e.target.checked })} /></td>
                  <td style={td}>{x.fecha}</td><td style={td}>{x.proveedor}<div style={{ color: theme.inkSoft }}>{x.concepto}</div></td>
                  <td style={{ ...td, textAlign: "right", whiteSpace: "nowrap" }}>{fmtEUR(x.importe)}</td>
                </tr>
              )))}

            <div style={{ fontSize: 12, color: theme.inkSoft, marginTop: 12 }}>
              Se guardan como gastos del club (importe con IVA incluido), con su proveedor, nº de factura y cuenta contable. Las facturas ya importadas no se duplican.
            </div>
            <div style={{ display: "flex", justifyContent: "flex-end", alignItems: "center", gap: 10, marginTop: 14 }}>
              {progreso && <span style={{ fontSize: 13, color: theme.inkSoft }}>Guardando {progreso.hechos} de {progreso.total}…</span>}
              <button onClick={() => { setItems(null); setArchivo(""); }} disabled={!!progreso} style={{ background: "#fff", border: `1px solid ${theme.border}`, borderRadius: 8, padding: "9px 14px", fontWeight: 600, cursor: "pointer", color: theme.inkSoft }}>Otro archivo</button>
              <button onClick={importar} disabled={!!progreso || aImportar.length === 0 || resumen.nueva + resumen.cambiada === 0}
                style={{ background: theme.accent, color: "#fff", border: "none", borderRadius: 8, padding: "9px 16px", fontWeight: 600, cursor: "pointer", opacity: progreso || resumen.nueva + resumen.cambiada === 0 ? 0.5 : 1 }}>
                Importar {resumen.nueva + resumen.cambiada} facturas
              </button>
            </div>
          </div>
        )}
        {error && <div style={{ background: "#FBEAE5", color: theme.danger, padding: 10, borderRadius: 10, fontSize: 13, marginTop: 12 }}>{error}</div>}
      </div>
    </div>
  );
}

// Mi nómina en Golf Ciudad Real (resúmenes de nómina de la gestoría): líquido pagado cada mes. "anticipo" = descuento de anticipos ya deducido del líquido.
const NOMINAS_JOSE_2026 = [
  { m: 1, dia: 31, bruto: 2703.40, liquido: 2100.00, anticipo: 0 },
  { m: 2, dia: 28, bruto: 2703.40, liquido: 2100.00, anticipo: 0 },
  { m: 3, dia: 31, bruto: 2701.99, liquido: 2100.00, anticipo: 0 },
  { m: 4, dia: 30, bruto: 2702.35, liquido: 1951.08, anticipo: 148.92 },
  { m: 5, dia: 31, bruto: 2702.35, liquido: 2100.00, anticipo: 0 },
  { m: 6, dia: 30, bruto: 2702.35, liquido: 1897.35, anticipo: 202.65 },
  { m: 7, dia: 31, bruto: 2702.35, liquido: 2100.00, anticipo: 0 },
  { m: 8, dia: 31, bruto: 2702.35, liquido: 2100.00, anticipo: 0 },
  { m: 9, dia: 30, bruto: 2702.35, liquido: 2100.00, anticipo: 0 },
  { m: 10, dia: 31, bruto: 2702.35, liquido: 2100.00, anticipo: 0 },
];

function TransaccionesView({ transacciones, onAdd, onAddVarios, onActualizar, onActualizarVarios, categorias, tenantId, entidad, negocio, onCambiarDestino, onCambiarPago, onBorrar }) {
  const [showForm, setShowForm] = useState(false);
  const [txEditando, setTxEditando] = useState(null);
  const [showScan, setShowScan] = useState(false);
  const [showImportar, setShowImportar] = useState(false);
  const [showProveedores, setShowProveedores] = useState(false);
  const [cargandoNominas, setCargandoNominas] = useState(false);
  // Carga mi nómina de 2026 como ingreso de la economía Personal (líquido de cada mes). Identificador fijo: no se duplica.
  const cargarMiNomina2026 = async () => {
    const MESES = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];
    const total = NOMINAS_JOSE_2026.reduce((a, x) => a + x.liquido, 0);
    if (!window.confirm(`Se va a cargar tu nómina de Golf Ciudad Real (${NOMINAS_JOSE_2026.length} meses, enero-${MESES[NOMINAS_JOSE_2026[NOMINAS_JOSE_2026.length - 1].m - 1]} 2026) como ingreso Personal:\n\n· Líquido total: ${fmtEUR(total)}\n· Forma de pago: Transferencia\n\nSi ya estaba cargada, se actualiza sin duplicarse. ¿Continuar?`)) return;
    setCargandoNominas(true);
    try {
      for (const x of NOMINAS_JOSE_2026) {
        const mm = String(x.m).padStart(2, "0");
        await setDoc(doc(db, `clubes/${tenantId}/finanzas_transacciones`, `nomina-jmcf-2026-${mm}`), {
          type: "income", category: "Nómina", subcategory: "", proveedor: "Golf Ciudad Real C.D.",
          description: `Nómina ${MESES[x.m - 1]} 2026 (bruto ${fmtEUR(x.bruto)})${x.anticipo ? ` · descontado anticipo de ${fmtEUR(x.anticipo)}` : ""}`,
          amount: x.liquido.toFixed(2), date: new Date(Date.UTC(2026, x.m - 1, x.dia)).toISOString(), activity: "", iva_type: "", base_amount: null, iva_amount: null,
          irpf_deductible: "no", metodo_pago: "Transferencia", entidad: "jmcf", negocio: "personal", origen: "nomina_personal", created_at: serverTimestamp(),
        });
      }
      window.alert(`Listo: ${NOMINAS_JOSE_2026.length} nóminas cargadas como ingreso Personal.`);
    } catch (e) {
      window.alert("No se ha podido cargar tu nómina: " + (e?.message || e));
    }
    setCargandoNominas(false);
  };
  const [datosDetectados, setDatosDetectados] = useState(null);
  // Carga las nóminas de 2026 (resúmenes de la gestoría) como gastos de personal del club: por mes, "Sueldos y salarios" y "Seguridad Social".
  // Cada una tiene un identificador fijo: si se vuelve a pulsar, se actualizan, no se duplican.
  const cargarNominas2026 = async () => {
    const MESES = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];
    const totalB = PYG_NOMINAS_2026.reduce((a, x) => a + x.bruto, 0);
    const totalS = PYG_NOMINAS_2026.reduce((a, x) => a + x.ss, 0);
    if (!window.confirm(`Se van a cargar las nóminas de ${PYG_NOMINAS_2026.length} meses (enero-${MESES[PYG_NOMINAS_2026[PYG_NOMINAS_2026.length - 1].m - 1]} 2026) como gastos del club:\n\n· Sueldos y salarios: ${fmtEUR(totalB)}\n· Seguridad Social a cargo de la empresa: ${fmtEUR(totalS)}\n\nSi ya estaban cargadas, se actualizan sin duplicarse. ¿Continuar?`)) return;
    setCargandoNominas(true);
    try {
      for (const x of PYG_NOMINAS_2026) {
        const mm = String(x.m).padStart(2, "0");
        const fecha = new Date(Date.UTC(2026, x.m, 0)).toISOString(); // último día del mes
        const comun = { type: "expense", subcategory: "", activity: "", iva_type: "", base_amount: null, iva_amount: null, irpf_deductible: "no", metodo_pago: "", entidad: "club", negocio: null, origen: "nominas", date: fecha, trabajadores: x.n };
        await setDoc(doc(db, `clubes/${tenantId}/finanzas_transacciones`, `nomina-2026-${mm}-sueldos`), {
          ...comun, category: "Sueldos y salarios", proveedor: "Nóminas", cuenta: "64000000",
          description: `Nóminas ${MESES[x.m - 1]} 2026 (${x.n} trabajadores)`, amount: x.bruto.toFixed(2), created_at: serverTimestamp(),
        });
        await setDoc(doc(db, `clubes/${tenantId}/finanzas_transacciones`, `nomina-2026-${mm}-ss`), {
          ...comun, category: "Seguridad Social", proveedor: "Seguridad Social (TGSS)", cuenta: "64200000",
          description: `Seguridad Social a cargo de la empresa, ${MESES[x.m - 1]} 2026`, amount: x.ss.toFixed(2), created_at: serverTimestamp(),
        });
      }
      window.alert(`Listo: ${PYG_NOMINAS_2026.length * 2} gastos de personal cargados en Golf Ciudad Real.`);
    } catch (e) {
      window.alert("No se han podido cargar las nóminas: " + (e?.message || e));
    }
    setCargandoNominas(false);
  };
  const [errorTicket, setErrorTicket] = useState("");
  const abrirTicket = async (t) => {
    setErrorTicket("");
    // En móvil/tablet (Safari, Chrome) las pestañas emergentes tras una espera se bloquean: se abre en la misma pestaña.
    const esMovil = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
    // En ordenador la pestaña se abre ANTES de la espera (si no, el navegador bloquea la ventana emergente).
    const w = esMovil ? null : window.open("", "_blank");
    try {
      const url = await getDownloadURL(ref(storage, t.ticket_path));
      if (w) w.location.href = url;
      else window.location.href = url;
    } catch (e) {
      if (w) w.close();
      setErrorTicket("No se ha podido abrir el archivo: " + (e?.code ? e.code + " · " : "") + (e?.message || e));
    }
  };
  const ordenadas = [...transacciones].sort(
    (a, b) => new Date(b.date) - new Date(a.date)
  );

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <div style={{ fontWeight: 700, fontSize: 18, color: theme.ink }}>Transacciones</div>
        <div style={{ display: "flex", gap: 8 }}>
          <button
            onClick={() => setShowImportar(true)}
            className="rounded-md"
            style={{
              display: "flex",
              alignItems: "center",
              gap: 6,
              background: "#fff",
              color: theme.pine,
              border: `1px solid ${theme.border}`,
              padding: "8px 14px",
              fontWeight: 600,
              cursor: "pointer",
            }}
          >
            <Upload size={16} /> Importar Excel/CSV
          </button>
          {entidad === "club" && (
            <button
              onClick={() => setShowProveedores(true)}
              className="rounded-md"
              style={{ display: "flex", alignItems: "center", gap: 6, background: "#fff", color: theme.pine, border: `1px solid ${theme.border}`, padding: "8px 14px", fontWeight: 600, cursor: "pointer" }}
            >
              <Upload size={16} /> Importar proveedores
            </button>
          )}
          {entidad === "jmcf" && (
            <button
              onClick={cargarMiNomina2026}
              disabled={cargandoNominas}
              className="rounded-md"
              style={{ display: "flex", alignItems: "center", gap: 6, background: "#fff", color: theme.pine, border: `1px solid ${theme.border}`, padding: "8px 14px", fontWeight: 600, cursor: "pointer", opacity: cargandoNominas ? 0.6 : 1 }}
            >
              <Upload size={16} /> {cargandoNominas ? "Cargando…" : "Cargar mi nómina 2026"}
            </button>
          )}
          {entidad === "club" && (
            <button
              onClick={cargarNominas2026}
              disabled={cargandoNominas}
              className="rounded-md"
              style={{ display: "flex", alignItems: "center", gap: 6, background: "#fff", color: theme.pine, border: `1px solid ${theme.border}`, padding: "8px 14px", fontWeight: 600, cursor: "pointer", opacity: cargandoNominas ? 0.6 : 1 }}
            >
              <Upload size={16} /> {cargandoNominas ? "Cargando…" : "Cargar nóminas 2026"}
            </button>
          )}
          <button
            onClick={() => setShowScan(true)}
            className="rounded-md"
            style={{
              display: "flex",
              alignItems: "center",
              gap: 6,
              background: "#fff",
              color: theme.accent,
              border: `1px solid ${theme.accent}`,
              padding: "8px 14px",
              fontWeight: 600,
              cursor: "pointer",
            }}
          >
            <Camera size={16} /> Escanear ticket
          </button>
          <button
            onClick={() => { setDatosDetectados(null); setShowForm(true); }}
            className="rounded-md"
            style={{
              display: "flex",
              alignItems: "center",
              gap: 6,
              background: theme.accent,
              color: "#fff",
              border: "none",
              padding: "8px 14px",
              fontWeight: 600,
              cursor: "pointer",
            }}
          >
            <Plus size={16} /> Nueva
          </button>
        </div>
      </div>

      {errorTicket && (
        <div style={{ background: "#FBEAE5", color: theme.danger, padding: 10, borderRadius: 10, fontSize: 13, marginBottom: 12 }}>{errorTicket}</div>
      )}
      <Card style={{ padding: 0 }}>
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ borderBottom: `1px solid ${theme.border}` }}>
              {["Fecha", "Categoría", "Proveedor", "Descripción", "Tipo", "Importe", "Destino", ...(entidad === "jmcf" ? ["Pago"] : []), "Archivo", ""].map((h) => (
                <th
                  key={h}
                  style={{
                    textAlign: "left",
                    padding: "12px 16px",
                    fontSize: 12,
                    color: theme.inkSoft,
                    fontWeight: 600,
                  }}
                >
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {ordenadas.map((t) => (
              <tr key={t.id} style={{ borderBottom: `1px solid ${theme.border}` }}>
                <td style={{ padding: "12px 16px", fontSize: 14 }}>{fmtDate(t.date)}</td>
                <td style={{ padding: "12px 16px", fontSize: 14 }}>{t.category}</td>
                <td style={{ padding: "12px 16px", fontSize: 14 }}>{t.proveedor || <span style={{ color: theme.border }}>—</span>}</td>
                <td style={{ padding: "12px 16px", fontSize: 14, color: theme.inkSoft }}>
                  {t.description || "—"}
                  {t.grupo_ticket && <div style={{ fontSize: 11.5, color: theme.accent, marginTop: 2 }}>✂ Ticket compartido{t.importe_ticket ? ` (total ${fmtEUR(t.importe_ticket)})` : ""}</div>}
                </td>
                <td style={{ padding: "12px 16px" }}>
                  <Badge tone={t.type === "income" ? "income" : "expense"}>
                    {t.type === "income" ? "Ingreso" : "Gasto"}
                  </Badge>
                </td>
                <td
                  style={{
                    padding: "12px 16px",
                    fontSize: 14,
                    fontWeight: 700,
                    color: t.type === "income" ? theme.success : theme.danger,
                  }}
                >
                  {t.type === "income" ? "+" : "-"} {fmtEUR(t.amount)}
                </td>
                <td style={{ padding: "12px 16px", fontSize: 13 }}>
                  {String(t.id).startsWith("academia-") ? (
                    <span style={{ color: theme.inkSoft }}>Academia</span>
                  ) : (
                    <select
                      value={destinoDeTx(t)}
                      onChange={(e) => onCambiarDestino && onCambiarDestino(t.id, e.target.value)}
                      style={{ padding: "4px 6px", borderRadius: 6, border: `1px solid ${destinoDeTx(t) === "sin" ? theme.warn : theme.border}`, fontSize: 12, background: "#fff" }}
                    >
                      <option value="sin" disabled>Sin asignar</option>
                      {DESTINOS.map(([id, n]) => <option key={id} value={id}>{n}</option>)}
                    </select>
                  )}
                </td>
                {entidad === "jmcf" && (
                  <td style={{ padding: "12px 16px", fontSize: 13 }}>
                    {String(t.id).startsWith("academia-") ? (
                      <span style={{ color: theme.inkSoft }}>{t.metodo_pago || "—"}</span>
                    ) : (
                      <select
                        value={t.metodo_pago || ""}
                        onChange={(e) => onCambiarPago && onCambiarPago(t.id, e.target.value)}
                        style={{ padding: "4px 6px", borderRadius: 6, border: `1px solid ${theme.border}`, fontSize: 12, background: "#fff" }}
                      >
                        <option value="">—</option>
                        {METODOS_PAGO.map((m) => <option key={m} value={m}>{m}</option>)}
                      </select>
                    )}
                  </td>
                )}
                <td style={{ padding: "12px 16px", fontSize: 13 }}>
                  {t.ticket_path ? (
                    <button
                      onClick={() => abrirTicket(t)}
                      title={t.ticket_nombre || "Ver archivo"}
                      style={{ border: `1px solid ${theme.border}`, background: "#fff", borderRadius: 6, padding: "3px 8px", cursor: "pointer", fontSize: 12 }}
                    >📎 Ver</button>
                  ) : (
                    <span style={{ color: theme.border }}>—</span>
                  )}
                </td>
                <td style={{ padding: "12px 8px", fontSize: 13 }}>
                  {!String(t.id).startsWith("academia-") && onActualizar && (
                    <button
                      onClick={() => { setTxEditando(t); setDatosDetectados(null); setShowForm(true); }}
                      title="Editar o repartir esta transacción"
                      style={{ border: "none", background: "transparent", cursor: "pointer", padding: 4, fontSize: 14 }}
                    >✏️</button>
                  )}
                  {!String(t.id).startsWith("academia-") && onBorrar && (
                    <button
                      onClick={() => onBorrar(t)}
                      title="Borrar esta transacción"
                      style={{ border: "none", background: "transparent", color: theme.danger, cursor: "pointer", padding: 4 }}
                    ><Trash2 size={16} /></button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </Card>

      {showScan && (
        <EscanearTicketModal
          tenantId={tenantId}
          onClose={() => setShowScan(false)}
          onDetectado={(datos) => {
            setDatosDetectados({ ...datos, entidad: "jmcf" }); // los tickets escaneados van siempre a JMCF
            setShowScan(false);
            setShowForm(true);
          }}
        />
      )}

      {showProveedores && (
        <ImportarProveedoresModal onClose={() => setShowProveedores(false)} tenantId={tenantId} transacciones={transacciones} />
      )}

      {showImportar && (
        <ImportarExcelModal
          onClose={() => setShowImportar(false)}
          onAdd={onAdd}
          categorias={categorias}
        />
      )}

      {showForm && (
        <TransaccionForm
          initial={txEditando ? null : datosDetectados}
          editando={txEditando}
          destinoInicial={entidad === "jmcf" ? (["proshop", "academia", "piso", "personal"].includes(negocio) ? negocio : "proshop") : "club"}
          categorias={categorias}
          onClose={() => { setShowForm(false); setDatosDetectados(null); setTxEditando(null); }}
          onSave={(data) => {
            onAdd(data);
            setShowForm(false);
            setDatosDetectados(null);
          }}
          onSaveVarios={(datas) => {
            onAddVarios && onAddVarios(datas);
            setShowForm(false);
            setDatosDetectados(null);
          }}
          onUpdate={(id, data) => {
            onActualizar && onActualizar(id, data);
            setShowForm(false);
            setTxEditando(null);
          }}
          onUpdateVarios={(id, datas) => {
            onActualizarVarios && onActualizarVarios(txEditando, datas);
            setShowForm(false);
            setTxEditando(null);
          }}
        />
      )}
    </div>
  );
}

